loginCheckJs:
let curUrl = result.url();
let bodyStr = result.body();
let isSearch = curUrl.includes("youduzw.com/sa");
let isVerified = bodyStr.includes("Just a moment...") || bodyStr.includes("onloadTurnstileCallback");

if (!isSearch && isVerified) {
    java.toast("❗身份验证过期");
    let freshUrl = `${curUrl}${curUrl.includes('?') ? '&' : '?'}_t=${Date.now()}`;
    result = java.startBrowserAwait(freshUrl, "Authentication");
} else {
    result = result;
}

